#include <stdio.h>

#define SQUARE(x) ((x) * (x))
#define HALF(x) ((x) / 2)

int main(void) {
    int a = 0;
    int b = 0;
    if (scanf("%d %d", &a, &b) != 2) {
        return 1;
    }

    printf("先合体再自己乘自己：%d 条喵\n", SQUARE(a + b));
    printf("合体之后再分一半：%d 条喵\n", HALF(a + b));

    return 0;
}
